func:
// Store the raw form input for later use (after HTTP response)
msg.config_variables = msg.payload;

msg.headers = {
    "Authorization": "Bearer " + msg.payload.rayvn_api_key
};

msg.url = global.get("parat_bridge").base_urls.rayvn + "/logs";

return msg;

let result = msg.payload;
let name = msg.config_variables.rayvn_log_name;

// Find the log id where the name matches
msg.payload = result.find(item => item.name === name)?.id;
return msg;

// resolved from log name in previous node
const log_id = msg.payload;
const sender_override = (msg.config_variables.rayvn_sender_name || "").trim() || null;
const log_name = msg.config_variables.rayvn_log_name;

const rayvn_config = {
    // Standard client contract fields
    client_system: "rayvn",
    api_key: msg.config_variables.rayvn_api_key,
    identifier: log_id,
    name: sender_override || log_name,
    timestamp: Date.now(),
    client_specific: {
        // Rayvn-specific fields
        api_key: msg.config_variables.rayvn_api_key,
        log_name: log_name,
        log_id: log_id,
        sender_override: sender_override
    }
};

msg.payload = rayvn_config;
return msg;

if (
    msg.payload.rayvn_api_key.length > 0 && 
    msg.payload.rayvn_log_name.length > 0
    ) 
    {
        return msg;
    } else {
        node.error("missing rayvn config in msg.payload: ", msg);
        return null
    }

const config = msg.payload;

msg.topic = config.client_system;

if (config.identifier && 
    config.client_specific.api_key && 
    config.client_specific.log_id) {
    return msg;
} else {
    node.error("Rayvn config not correctly configured", config);
    return null;
}
